    /// <summary>
    /// Gap T3: 303 forces follow-up to GET and drops body per RFC 7231 §6.4.4.
    /// </summary>
    [Fact]
    public async Task BhvRedirects005Redirect303SwitchesToGetAndDropsBody()
    {
        var transport = TransportOptions.Builder().FollowRedirects(true).MaxRedirects(5).Build();

        var client = new DefaultApiClient(transport);
        var headers = new Dictionary<string, string> { { "Content-Type", "application/json" } };
        var response = await client.SendRequestAsync(
            "POST",
            new Uri(_fixture.BaseUrl + "/test/redirect/303"),
            headers,
            "hello-body"
        );

        Assert.Equal(200, response.StatusCode);
        var json = JsonDocument.Parse(response.Body);
        Assert.Equal("GET", json.RootElement.GetProperty("method").GetString());
        Assert.Equal("", json.RootElement.GetProperty("body").GetString());
    }

    // Canonical scenario N1: an HTTPS->HTTP downgrade redirect carrying a body.
    // A 302 forces the follow-up to GET and drops the body (per RFC the request
    // becomes GET), so the hop PROCEEDS — nothing sensitive is replayed in
    // cleartext. A 307/308 would preserve method+body, so replaying it over the
    // downgraded cleartext leg is refused with a typed ApiException. These two
    // mock-handler cases are fixture-independent; node guards every status
    // (throws where others proceed), the canonical guards 307/308 only.

    [Fact]
    public async Task BhvRedirects001Downgrade302WithBodyProceedsAsGet()
    {
        var handler = new DowngradeRedirectHandler(
            firstStatus: HttpStatusCode.Redirect, // 302
            location: new Uri("http://downgraded.example.com/landed")
        );
        var client = new DefaultApiClient(new HttpClient(handler));

        var response = await client.SendRequestAsync(
            "POST",
            new Uri("https://secure.example.com/start"),
            new Dictionary<string, string>(),
            "secret-payload"
        );

        // The 302 downgrade proceeds: the body is dropped and the follow-up is
        // a GET, so the downgrade body-replay guard does not fire.
        Assert.Equal(200, response.StatusCode);
        Assert.Equal(2, handler.Requests.Count);
        Assert.Equal(HttpMethod.Get, handler.Requests[1].Method);
    }

    [Theory]
    [InlineData(301, "POST", "GET", false)]
    [InlineData(302, "POST", "GET", false)]
    [InlineData(301, "PUT", "PUT", true)]
    [InlineData(302, "PATCH", "PATCH", true)]
    [InlineData(302, "DELETE", "DELETE", true)]
    [InlineData(303, "PUT", "GET", false)]
    [InlineData(303, "POST", "GET", false)]
    [InlineData(303, "HEAD", "HEAD", false)]
    [InlineData(307, "PUT", "PUT", true)]
    [InlineData(308, "DELETE", "DELETE", true)]
    public async Task RedirectRewritesTheMethodPerRfc9110(
        int status,
        string method,
        string expectedMethod,
        bool expectedBody
    )
    {
        var handler = new DowngradeRedirectHandler(
            firstStatus: (HttpStatusCode)status,
            location: new Uri("http://secure.example.com/landed")
        );
        var client = new DefaultApiClient(new HttpClient(handler));

        var response = await client.SendRequestAsync(
            method,
            new Uri("http://secure.example.com/start"),
            new Dictionary<string, string>(),
            method == "HEAD" ? null : "payload"
        );

        Assert.Equal(200, response.StatusCode);
        Assert.Equal(2, handler.Requests.Count);
        Assert.Equal(new HttpMethod(expectedMethod), handler.Requests[1].Method);
        Assert.Equal(expectedBody, handler.HadBody[1]);
    }

    [Fact]
    public async Task BhvRetries010Downgrade307WithBodyThrows()
    {
        var handler = new DowngradeRedirectHandler(
            firstStatus: HttpStatusCode.RedirectKeepVerb, // 307
            location: new Uri("http://downgraded.example.com/landed")
        );
        var client = new DefaultApiClient(new HttpClient(handler));

        // 307 preserves method+body; replaying it across the HTTPS->HTTP
        // downgrade in cleartext is refused as a typed SDK error.
        var ex = await Assert.ThrowsAsync<ApiException>(() =>
            client.SendRequestAsync(
                "POST",
                new Uri("https://secure.example.com/start"),
                new Dictionary<string, string>(),
                "secret-payload"
            )
        );

        Assert.Single(handler.Requests);
        Assert.Contains("downgrade", ex.Message, StringComparison.OrdinalIgnoreCase);
        // A refused redirect is a response that arrived but could not be
        // used: ApiException carrying the redirect's real status.
        Assert.Equal(307, ex.StatusCode);
    }

    [Fact]
    public async Task BhvRetries011Downgrade308WithBodyThrows()
    {
        var handler = new DowngradeRedirectHandler(
            firstStatus: HttpStatusCode.PermanentRedirect, // 308
            location: new Uri("http://downgraded.example.com/landed")
        );
        var client = new DefaultApiClient(new HttpClient(handler));

        // 308 preserves method+body, so the replay across the HTTPS->HTTP
        // downgrade is refused as a typed SDK error, as for 307.
        var ex = await Assert.ThrowsAsync<ApiException>(() =>
            client.SendRequestAsync(
                "POST",
                new Uri("https://secure.example.com/start"),
                new Dictionary<string, string>(),
                "secret-payload"
            )
        );

        Assert.Single(handler.Requests);
        Assert.Contains("downgrade", ex.Message, StringComparison.OrdinalIgnoreCase);
        Assert.Equal(308, ex.StatusCode);
    }

