    /// <summary>
    /// First request returns <paramref name="firstStatus"/> with a Location
    /// header pointing at <paramref name="location"/> (used here to model an
    /// HTTPS->HTTP downgrade); subsequent requests return 200 OK. Records each
    /// request so N1 can assert the hop count and the follow-up method.
    /// </summary>
    private sealed class DowngradeRedirectHandler : HttpMessageHandler
    {
        private readonly HttpStatusCode _firstStatus;
        private readonly Uri _location;
        public List<HttpRequestMessage> Requests { get; } = [];
        public List<bool> HadBody { get; } = [];

        public DowngradeRedirectHandler(HttpStatusCode firstStatus, Uri location)
        {
            _firstStatus = firstStatus;
            _location = location;
        }

        protected override Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request,
            CancellationToken cancellationToken
        )
        {
            // Snapshot the request — DefaultApiClient disposes it after the
            // redirect hop, which would otherwise clear Method/Headers.
            var snapshot = new HttpRequestMessage(request.Method, request.RequestUri);
            foreach (var h in request.Headers)
            {
                snapshot.Headers.TryAddWithoutValidation(h.Key, h.Value);
            }
            Requests.Add(snapshot);
            HadBody.Add(request.Content != null);

            if (Requests.Count == 1)
            {
                var redirect = new HttpResponseMessage(_firstStatus)
                {
                    Content = new StringContent(""),
                };
                redirect.Headers.Location = _location;
                return Task.FromResult(redirect);
            }
            return Task.FromResult(
                new HttpResponseMessage(HttpStatusCode.OK) { Content = new StringContent("") }
            );
        }
    }

    /// <summary>
    /// Stateless redirect-chain handler: a request to /chain/{n} with n above 0
    /// returns a 302 pointing at /chain/{n-1}; /chain/0 returns 200 OK. The
    /// chain length lives entirely in the URL, so the handler holds no
    /// per-request state and can serve many concurrent chains of different
    /// lengths through one HttpClient without interfering between them.
    /// </summary>
    private sealed class ChainRedirectHandler : HttpMessageHandler
    {
        protected override Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request,
            CancellationToken cancellationToken
        )
        {
            var path = request.RequestUri!.AbsolutePath;
            var remaining = int.Parse(
                path.AsSpan(path.LastIndexOf('/') + 1),
                System.Globalization.CultureInfo.InvariantCulture
            );
            if (remaining <= 0)
            {
                return Task.FromResult(
                    new HttpResponseMessage(HttpStatusCode.OK) { Content = new StringContent("") }
                );
            }

            var redirect = new HttpResponseMessage(HttpStatusCode.Found)
            {
                Content = new StringContent(""),
            };
            redirect.Headers.Location = new Uri(request.RequestUri, $"/chain/{remaining - 1}");
            return Task.FromResult(redirect);
        }
    }
